const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/todos/store.cjs');
test('store appends records and keeps returned data detached', () => {
  const initial = [{ id: 'old', title: 'Keep me' }];
  const store = createStore(initial);
  initial[0].title = 'mutated input';
  store.addAll([{ id: 'new', title: 'Added' }]);
  const snapshot = store.list();
  snapshot[0].title = 'mutated output';
  assert.deepEqual(store.list(), [{ id: 'old', title: 'Keep me' }, { id: 'new', title: 'Added' }]);
});

