const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/todos/store.cjs');
const { importTodos } = require('../src/todos/import.cjs');
test('valid import appends the whole batch without replacing old records', () => {
  const before = [{ id: 'old', title: 'Keep me' }];
  const added = [{ id: 'a', title: 'Read' }, { id: 'b', title: 'Walk' }];
  const store = createStore(before);
  importTodos(JSON.stringify(added), store);
  assert.deepEqual(store.list(), [...before, ...added]);
});
for (const [label, input, error] of [
  ['invalid JSON', '{broken', /json|解析|语法/i],
  ['empty title after a valid record', '[{"id":"ok","title":"Valid"},{"id":"blank","title":"  "}]', /title|标题/i],
  ['duplicate ID within batch', '[{"id":"dup","title":"One"},{"id":"dup","title":"Two"}]', /id|标识/i],
  ['existing ID conflict after a valid record', '[{"id":"ok","title":"Valid"},{"id":"old","title":"Conflict"}]', /id|标识/i]
]) test(label + ' rejects the whole batch and identifies the error', () => {
  const before = [{ id: 'old', title: 'Keep me' }], store = createStore(before);
  assert.throws(() => importTodos(input, store), error);
  assert.deepEqual(store.list(), before);
});

