test('all supported themes are returned unchanged', () => {
  for (const theme of ['light', 'dark', 'auto']) assert.equal(readTheme({ theme }), theme);
});
test('missing theme uses auto and leaves other settings unchanged', () => {
  const config = { fontSize: 16 };
  assert.equal(readTheme(config), 'auto');
  assert.deepEqual(config, { fontSize: 16 });
});
