const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const root = path.resolve(__dirname, '..');
test('standalone generator writes a portable ordered index from an actual manifest', t => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'atlas-index-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const input = path.join(root, 'assets/manifest.json'), output = path.join(dir, 'generated/atlas-index.json');
  const result = spawnSync(process.execPath, [path.join(root, 'src/tools/build-atlas-index.cjs'), input, output], { encoding: 'utf8', windowsHide: true, timeout: 5000 });
  assert.equal(result.status, 0, result.stderr);
  const frames = JSON.parse(fs.readFileSync(input, 'utf8')).frames;
  assert.deepEqual(JSON.parse(fs.readFileSync(output, 'utf8')), { schemaVersion: 1, frames });
});

