const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { loadTimeline } = require('../src/preview/timeline.cjs');
const root = path.resolve(__dirname, '..');
test('preview consumes generated frame order, dimensions and per-frame timing', t => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'atlas-preview-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  for (const frames of [
    [{ path: 'idle-1.png', width: 32, height: 48, durationMs: 80 }, { path: 'idle-2.png', width: 32, height: 48, durationMs: 120 }],
    [{ path: 'attack-a.png', width: 64, height: 60, durationMs: 35 }, { path: 'attack-b.png', width: 65, height: 61, durationMs: 75 }, { path: 'attack-c.png', width: 66, height: 62, durationMs: 50 }]
  ]) {
    const input = path.join(dir, 'manifest.json'), output = path.join(dir, 'generated/atlas-index.json');
    fs.writeFileSync(input, JSON.stringify({ frames }));
    const result = spawnSync(process.execPath, [path.join(root, 'src/tools/build-atlas-index.cjs'), input, output], { encoding: 'utf8', windowsHide: true, timeout: 5000 });
    assert.equal(result.status, 0, result.stderr);
    let elapsed = 0;
    const expected = frames.map(({ path, width, height, durationMs }) => {
      const startMs = elapsed; elapsed += durationMs;
      return { path, width, height, startMs, endMs: elapsed };
    });
    assert.deepEqual(loadTimeline(output), expected);
  }
});

