const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
test('scene metadata names existing portrait scene files; this is not a touch runtime check', () => {
  const meta = JSON.parse(fs.readFileSync(path.join(root, 'src/battle/scene-metadata.json'), 'utf8'));
  assert.equal(meta.orientation, 'portrait');
  assert.equal(meta.width, 1080); assert.equal(meta.height, 1920);
  assert.ok(fs.statSync(path.join(root, meta.scene)).isFile());
  assert.ok(fs.statSync(path.join(root, meta.script)).isFile());
});
